const edition = globalThis.makeSubjectEdition({"year":2016,"grade":"7-8","tasksFile":"7-8_2.pdf","answersFile":"reviewed-7-8-v2.pdf","title":"XVII век. Россия накануне перемен","variant":"2","variantLabel":"Вариант 2","subject":"golden-fleece","contest":"Золотое руно","letters":"ABCD","count":60,"language":"ru","points":3,"sourceFile":"sources/golden-fleece/2016/7-8-v2.json","editionSuffix":"v2","editionLabel":"Вариант 2","sections":[{"start":1,"title":"Московская держава"},{"start":16,"title":"Бунташный век"},{"start":31,"title":"В избах, теремах, храмах"},{"start":41,"title":"Вертоград многоцветный"},{"start":51,"title":"Русский стиль"}],"reviewedKey":true}, [{"title":"Начало собрания законов","question":"Какой документ открывает первое Полное собрание законов Российской империи?","choices":["Решение об избрании царём Михаила Романова","Соборное уложение 1649 года","Решение Земского собора об отказе присоединять Азов","Соборное решение об отмене местничества"],"answer":1,"steps":["Первое Полное собрание законов вышло в 1830 году и расположило документы по времени их принятия.","Оно начинается с Соборного уложения 1649 года — свода законов, принятого в царствование Алексея Михайловича."],"references":["https://www.prlib.ru/section/681958","https://www.prlib.ru/section/1951009"],"taskUrl":"https://runodog.ru/ZR_1516/7-8_2.pdf#page=1","adaptation":"Редакция вопроса проверена по первоисточникам."},{"title":"Чин в Боярской думе","question":"В состав Боярской думы в XVII веке входили …","choices":["окольничие","стольники","стряпчие","воеводы"],"answer":0,"steps":["Окольничий был думным чином ниже боярина.","Обладатели обоих чинов участвовали в обсуждении дел при государе."]},{"title":"Поставки в Европу","question":"Россия оказала влияние на ход Тридцатилетней войны в Европе тем, что …","choices":["поставляла оружие Австрии","продавала зерно Швеции","была посредником на переговорах с Испанией","послала свою армию в Германию"],"answer":1,"steps":["Русское государство продавало Швеции зерно по выгодным для неё условиям.","Торговля помогла шведам снабжать войска в ходе Тридцатилетней войны."]},{"title":"Глава русской делегации","question":"На Переяславской Раде 8 января 1654 года русскую делегацию возглавлял …","choices":["В. Бутурлин","И. Хованский","Ф. Шереметев","Б. Морозов"],"answer":0,"steps":["Боярин Василий Бутурлин приехал в Переяславль как представитель царя.","Он принимал присягу гетмана и участников рады."]},{"title":"Грамота семье Сусанина","question":"В грамоте царя Михаила Федоровича, выданной семье Ивана Сусанина, о подвиге героя говорилось, что он …","choices":["не выдал местонахождение будущего царя","завел вражеское войско в лесные дебри","убил командира вражеского отряда","взорвал себя вместе с врагами"],"answer":0,"steps":["Жалованная грамота 1619 года рассказывает, что Михаила пытались разыскать.","Сусанина пытали, добиваясь сведений, но он не открыл местонахождение царя."]},{"title":"Переговорщик в Андрусове","question":"Со стороны России переговоры с Речью Посполитой, закончившиеся Андрусовским перемирием в 1667 году, вел …","choices":["Ф. Ртищев","А. Ордин-Нащокин","Б. Морозов","А. Матвеев"],"answer":1,"steps":["Афанасий Ордин-Нащокин вёл переговоры с представителями Речи Посполитой.","По перемирию Россия получила, в частности, Смоленск и Левобережье."]},{"title":"Начальник двух походов","question":"Командующим русской армией во время Крымских походов 1687 и 1689 годов был …","choices":["В. Голицын","П. Гордон","Г. Ромодановский","И. Хованский"],"answer":0,"steps":["Василий Голицын возглавлял походы к Крыму при правлении Софьи.","Экспедициям мешали нехватка воды и припасов в степи."]},{"title":"Назначения на службу","question":"Военными и гражданскими служебными назначениями в России XVII века ведал …","choices":["Счетный приказ","приказ Большой казны","Казенный приказ","Разрядный приказ"],"answer":3,"steps":["В Разрядном приказе вели списки служилых людей.","Приказ ведал назначениями воевод и продвижением по службе."]},{"title":"Автор торговых правил","question":"Непосредственное участие в создании Новоторгового устава 1667 года принимал …","choices":["Б. Морозов","А. Ордин-Нащокин","Ф. Ртищев","А. Матвеев"],"answer":1,"steps":["Ордин-Нащокин участвовал в разработке правил, которые давали преимущества русским купцам.","Новоторговый устав ограничивал розничную торговлю иностранцев."]},{"title":"Посредник в переговорах","question":"По просьбе России посредником на переговорах о мире со Швецией в 1615-1617 годах выступал представитель …","choices":["Речи Посполитой","Священной Римской империи","Англии","Турции"],"answer":2,"steps":["Английский купец и дипломат Джон Меррик участвовал в переговорах России со Швецией.","Они завершились заключением Столбовского мира."]},{"title":"Граница после войны","question":"В результате русско-шведской войны 1656-1658 годов граница между странами …","choices":["не изменилась","прошла по рекам Нева и Нарова","прошла по реке Неве","прошла по рекам Нева и Свирь"],"answer":0,"steps":["Сначала Россия удерживала ряд завоёванных в войне пунктов по временному перемирию.","По Кардисскому миру пришлось вернуть их, и граница восстановилась."]},{"title":"Царский запрет 1634 года","question":"В 1634 году был издан указ, под страхом смерти запрещавший употребление …","choices":["ревеня","кофе","чая","табака"],"answer":3,"steps":["Табак завозили из-за границы, но московские власти связывали курение с нарушением порядка и пожарами.","За торговлю и употребление табака полагались строгие наказания."]},{"title":"Итог войны за Смоленск","question":"В результате Смоленской войны 1632-1634 годов …","choices":["был освобожден Смоленск","была разбита армия Речи Посполитой","польский король отказался от русской короны","была возвращена Северская Украина"],"answer":2,"steps":["Поляновский мир сохранил Смоленск за Речью Посполитой.","По тому же договору Владислав IV отказался от претензий на московский престол."]},{"title":"Род занятий Шорина","question":"Василий Шорин, один из богатейших людей России XVII века, был …","choices":["полководцем","дипломатом","священнослужителем","купцом"],"answer":3,"steps":["Василий Шорин принадлежал к богатым купцам, которых называли гостями.","Он вёл крупную торговлю, связанную в том числе с Волгой."]},{"title":"Голицын при дворе","question":"Василий Голицын играл видную роль в управлении Россией при …","choices":["Борисе Годунове","Василии Шуйском","царевне Софье","Петре I"],"answer":2,"steps":["Василий Голицын возглавлял внешнюю политику, когда при малолетних царях правила Софья.","Он участвовал в заключении «Вечного мира» с Речью Посполитой."]},{"title":"Кто назвался Дмитрием","question":"Правительство Бориса Годунова утверждало, что человек, выдававший себя за царевича Дмитрия, – это …","choices":["монах Варлаам","монах Мисаил","монах Григорий Отрепьев","учитель из Шклова"],"answer":2,"steps":["Правительство Годунова доказывало, что претендент лишь выдаёт себя за погибшего царевича.","Его официально называли беглым монахом Отрепьевым."]},{"title":"Кем назвался Болотников","question":"Иван Болотников называл себя …","choices":["народным вождем","воеводой царя Василия Шуйского","воеводой царя Дмитрия","царем"],"answer":2,"steps":["Болотников ссылался на власть якобы спасшегося царя Дмитрия.","Он действовал как его воевода, что позволяло обосновывать выступление против Шуйского."]},{"title":"Против церковных реформ","question":"Боярыня Ф. Морозова и княгиня Е. Урусова подверглись преследованиям за то, что …","choices":["поддерживали реформы патриарха Никона","отвергали реформы Никона","защищали права женщин","выступали за реформы по европейскому образцу"],"answer":1,"steps":["Морозова и Урусова придерживались прежних церковных обрядов и отказались принять реформу Никона.","Позиция сестёр привела к заключению."]},{"title":"Исход битвы на Волге","question":"Решающим событием восстания под предводительством Степана Разина стала битва за город …","choices":["Архангельск","Симбирск","Москву","Кострому"],"answer":1,"steps":["Войско Разина осадило Симбирск.","Пришедшие к городу правительственные войска разбили его армию, после чего восстание пошло на спад."]},{"title":"Мятеж 1682 года","question":"Бунт стрельцов в 1682 году вошел в историю под названием …","choices":["«Разинщина»","«Медный бунт»","«Хованщина»","«Соляной бунт»"],"answer":2,"steps":["Стрельцы выступили во время спора о престолонаследии.","Один из руководителей, князь Иван Хованский, дал имя событиям, названным Хованщиной."]},{"title":"Осада обители","question":"В период Смутного времени оборона этого монастыря сыграла важную роль в спасении страны.","choices":["Чудов","Кирилло-Белозерский","Соловецкий","Троице-Сергиев"],"answer":3,"steps":["Троице-Сергиев монастырь защищался от войск Сапеги и Лисовского.","Длительная оборона важной крепости ослабила осаждавших."]},{"title":"Медные и серебряные деньги","question":"«Медный бунт» 1662 года был вызван тем, что правительство платило жалованье медными деньгами, а налоги собирало …","choices":["серебром","бумажными деньгами","мехами","золотом"],"answer":0,"steps":["Жалованье выдавали медной монетой, которая быстро теряла цену.","Требование уплачивать налоги серебром ухудшало положение людей."]},{"title":"Вождь Первого ополчения","question":"В 1611 году одним из вождей Первого ополчения был рязанский дворянин …","choices":["И. Заруцкий","П. Ляпунов","Д. Трубецкой","А. Телятевский"],"answer":1,"steps":["Рязанский дворянин Прокопий Ляпунов собрал силы для похода к Москве.","Он вошёл в руководство Первого ополчения вместе с Заруцким и Трубецким."]},{"title":"Обитель старого обряда","question":"Этот монастырь стал центром восстания староверов (старообрядцев) в 1668-1676 годах.","choices":["Кирилло-Белозерский","Ново-Иерусалимский","Троице-Сергиев","Соловецкий"],"answer":3,"steps":["Монахи Соловецкого монастыря отказались пользоваться исправленными богослужебными книгами.","Войска осаждали укреплённую обитель несколько лет."]},{"title":"Бунт из-за хлеба","question":"В этом городе в 1650 году из-за роста цен на хлеб произошло одно из самых крупных народных восстаний XVII века.","choices":["Псков","Курск","Великий Устюг","Тобольск"],"answer":0,"steps":["В Пскове рост цены хлеба вызвал выступление горожан в 1650 году.","Движение распространилось в условиях споров о поставках зерна и действиях властей."]},{"title":"Куда ушёл Пётр","question":"В августе 1689 года этот монастырь стал местом сбора сил сторонников царя Петра.","choices":["Чудов","Донской","Данилов","Троице-Сергиев"],"answer":3,"steps":["В 1689 году Пётр укрылся в стенах Троице-Сергиева монастыря.","Туда к нему пришли сторонники, в том числе служилые люди и верные полки."]},{"title":"Призыв к переделу","question":"В период Смутного времени делить имущество бояр призывал …","choices":["К. Минин","Лжедмитрий I","П. Ляпунов","И. Болотников"],"answer":3,"steps":["Участники движения Болотникова осаждали Москву в борьбе с Василием Шуйским.","В прокламациях сторонников восстания звучали обещания земли и имущества бояр."]},{"title":"Поход перед восстанием","question":"Восстанию под руководством Степана Разина предшествовал поход под предводительством …","choices":["В. Уса","И. Болотникова","К. Булавина","И. Горчакова"],"answer":0,"steps":["Василий Ус вывел отряд донских казаков к центральным областям страны.","Позднее он присоединился к движению Разина."]},{"title":"Кто поднял холопов","question":"Предводителем восстания холопов в начале XVII века был …","choices":["В. Ус","И. Болотников","С. Разин","Хлопко Косолап"],"answer":3,"steps":["Во время голода и беспорядков начала XVII века действовал отряд Хлопка Косолапа.","В него входили беглые холопы, оставшиеся без содержания."]},{"title":"Первые противники Никона","question":"Одним из первых против реформы патриарха Никона выступил …","choices":["Симеон Полоцкий","Петр Могила","Епифаний Славинецкий","Аввакум Петров"],"answer":3,"steps":["Аввакум выступил против исправления книг и обрядов.","За сопротивление церковным властям его отправляли в ссылки."]},{"title":"Стиль московских храмов","question":"Подобные архитектурные сооружения получили общее стилевое название по фамилии родственников царя.","choices":["Голицыны","Нарышкины","Салтыковы","Мстиславские"],"answer":1,"steps":["В таких церквях заметны убывающие кверху ярусы и нарядный белый декор.","Многие постройки заказало семейство Нарышкиных, давшее название стилю."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/31.webp","alt":"Многоярусный храм с пышным убранством","width":167,"height":141}},{"title":"Живоподобие в иконе","question":"Этот иконописец стремился к «живоподобию» изображаемых людей.","choices":["С. Ушаков","П. Чирин","А. Рублев","Дионисий"],"answer":0,"steps":["Симон Ушаков уделял внимание мягким переходам света и тени на лицах.","Так он приближал иконные образы к тому, как выглядит живой человек."]},{"title":"Шатёр над храмом","question":"Этот деревянный храм, построенный в XVII веке на севере Руси, является образцом шатрового стиля.","choices":["Церковь Покрова близ Вытегры","Тихвинская церковь в Торжке","Церковь Успения в Варгузе","Преображенская церковь в Кижах"],"answer":2,"steps":["Шатровое завершение напоминает высокую многогранную пирамиду.","В храме Успения в Варзуге оно поднимается над деревянным основанием."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/33.webp","alt":"Деревянный храм с высоким шатром","width":132,"height":125}},{"title":"Листы с гравюрами","question":"Гравюры на меди в XVII веке в России назывались …","choices":["флемская резьба","белорусская резь","фряжские листы","парсуны"],"answer":2,"steps":["«Фряжскими» на Руси могли называть изделия или манеру западноевропейского происхождения.","Слово употребляли и в названии гравированных листов."]},{"title":"Ярославская роспись","question":"В росписи этого ярославского храма включены реалистические изображения Саломеи и Вирсавии.","choices":["Собор Спасского монастыря","Церковь Ильи Пророка","Церковь Иоанна Предтечи","Благовещенско-Яковлевская церковь"],"answer":2,"steps":["Церковь Иоанна Предтечи в Толчкове известна обширными настенными росписями.","В них соседствуют библейские сцены и узнаваемые бытовые подробности."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/35.webp","alt":"Зелёная церковь с пятью тёмными главами","width":168,"height":133}},{"title":"Действо в храме","question":"«Пещное действо» разыгрывалось …","choices":["в райках и вертепах","в трактирах","в кафедральных соборах","в монастырях"],"answer":2,"steps":["Пещное действо показывало библейскую историю о трёх отроках в огненной печи.","Его исполняли перед Рождеством в кафедральных соборах."]},{"title":"Звон над церковью","question":"Такой тип церковного здания, характерный для «нарышкинского барокко», назывался …","choices":["ротонда","«под колоколы»","корабль","базилика"],"answer":1,"steps":["В зданиях «под колоколы» ярус со звоном входит в сам объём храма.","Это заметно по открытым аркам над основным помещением."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/37.webp","alt":"Красная церковь с ярусной колокольней","width":132,"height":133}},{"title":"Стихи и музыка","question":"Этот композитор XVII века переложил на музыку стихотворную Псалтирь Симеона Полоцкого.","choices":["Н. Дилецкий","В. Титов","Д. Бортнянский","Н. Калашников"],"answer":1,"steps":["Симеон Полоцкий переложил псалмы в стихи.","Василий Титов создал для этих текстов многоголосную музыку."]},{"title":"Слобода иконописцев","question":"Вокруг этой церкви в XVII веке селились иконописцы Оружейной палаты.","choices":["Филиппа митрополита в Мещанской слободе","Воскресения Словущего на Успенском вражке","Спасо-Преображения на Арбате","Воскресения Словущего на Арбате"],"answer":3,"steps":["Поблизости от Арбата жили мастера, работавшие для Оружейной палаты.","Их приход связывают с церковью Воскресения Словущего."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/39.webp","alt":"Красный храм с белыми наличниками","width":132,"height":136}},{"title":"Место рождения эмали","question":"Техника расписной эмали, получившая распространение в XVII веке, называлась …","choices":["ростовская финифть","жостовская роспись","усольская эмаль","великоустюжская филигрань"],"answer":2,"steps":["Название усольской эмали связано с Сольвычегодском, который прежде называли Усольем.","Мастера расписывали эмаль по белому фону и закрепляли рисунок обжигом."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/40.webp","alt":"Тарелка с цветочным орнаментом","width":128,"height":130}},{"title":"Свидетель осады","question":"Автор сказания об обороне Троице-Сергиевой обители был …","choices":["тысяцким","архимандритом","келарем","думным дьяком"],"answer":2,"steps":["Авраамий Палицын написал сказание об осаде Троице-Сергиева монастыря.","Он был келарем, то есть ведал хозяйственными делами обители."]},{"title":"Всадник в сказании","question":"Для того чтобы справиться с Ананием Селевиным, поляки, согласно повести Авраамия Палицына, …","choices":["убили его коня","выстрелили по нему из пушки","устроили ему засаду","поссорили его с Александром Лисовским"],"answer":0,"steps":["Ананий Селевин в сказании проявляет храбрость, действуя верхом.","Противники лишают его преимущества, убив коня."]},{"title":"Кто поёт о походе","question":"Кто в народной песне похвалялся: «Мы веслом махнем – корабль возьмем, кистенем махнем – караван собьем»?","choices":["Стрельцы","Войска «Тушинского вора»","Турки","Казаки Степана Разина"],"answer":3,"steps":["В песенном образе действуют речные отряды, нападающие на корабли и караваны.","Эти слова приписаны казакам Разина."]},{"title":"Стихи для начинающих","question":"Карион Истомин включал свои вирши в …","choices":["школьные драмы","буквари","жития святых","переводы Августина Блаженного"],"answer":1,"steps":["Карион Истомин включал в иллюстрированные буквари вирши, то есть стихи.","Они помогали запомнить буквы и связанные с ними слова."]},{"title":"«Думы» о подвиге","question":"Одно из стихотворений цикла «Думы» этого поэта посвящено подвигу Ивана Сусанина.","choices":["К. Рылеев","А. Пушкин","Н. Карамзин","В. Жуковский"],"answer":0,"steps":["Кондратий Рылеев посвятил одну из «Дум» Ивану Сусанину.","В ней крестьянин уводит людей, разыскивающих Михаила Романова."]},{"title":"Хлеб в неурожай","question":"Главная героиня «Повести об Ульянии Осоргиной» пекла сладкий хлеб из …","choices":["муки и меда","лебеды и коры","ореховой скорлупы","лесных ягод"],"answer":1,"steps":["Героиня повести кормит людей, когда обычных запасов уже нет.","Хлеб из лебеды и коры показывает, насколько тяжёлым был голод."]},{"title":"Горе во сне","question":"Герою «Повести о Горе-Злосчастии» Горе явилось во сне в облике …","choices":["злой вороны","невесты на пиру","архангела Гавриила","братца названного"],"answer":2,"steps":["Горе-Злосчастие принимает облик вестника и является молодцу во сне.","В повести это архангел Гавриил."]},{"title":"Что такое раёк","question":"Раек, популярный в народной литературе XVII века, – это …","choices":["летописная повесть","жанр сказочной повести","церковный гимн","форма рифмованного стиха"],"answer":3,"steps":["Строки раёшного стиха соединяются рифмой и могут иметь неодинаковую длину.","Такая форма подходит для речевого ритма устного рассказа."]},{"title":"«Сыны тьмы»","question":"Симеон Полоцкий называл «сынами тьмы» …","choices":["пьяниц","разбойников","стрельцов","купцов"],"answer":3,"steps":["Симеон Полоцкий использовал образы света и тьмы, обличая жадность.","В обсуждаемом стихотворении это название относится к купцам."]},{"title":"Взаимная помощь","question":"Протопоп Аввакум в Житии рассказывает, что отношения с сибирскими «иноземцами» наладились после того, как …","choices":["он купил у них медвежьи шкуры","они приняли христианство","Настасья Марковна подружилась с их женщинами","татары стали воевать с башкирами"],"answer":2,"steps":["Жена Аввакума Настасья Марковна искала общий язык с местными жителями в Сибири.","Её общение с женщинами помогло семье наладить отношения."]},{"title":"Персонаж оперы","question":"Этого героя оперы М. Мусоргского «Борис Годунов» нет в тексте одноименной трагедии А. Пушкина.","choices":["Юродивый","Иезуит Рангони","Царевна Ксения","Варлаам"],"answer":1,"steps":["В польских сценах оперы иезуит Рангони убеждает Марину Мнишек поддержать самозванца.","Мусоргский ввёл эту фигуру при переработке пушкинского сюжета."]},{"title":"Картины старой Москвы","question":"Автор этой картины известен полотнами, изображающими московский быт XVII века.","choices":["А. Васнецов","А. Рябушкин","В. Суриков","Н. Рерих"],"answer":1,"steps":["Андрей Рябушкин изучал старинную одежду, утварь и архитектуру.","Эти детали он использовал в жанровых сценах о московской жизни XVII века."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/52.webp","alt":"Старинная городская улица с церковью","width":128,"height":187}},{"title":"Поздний храм в старом стиле","question":"Этот храм, построенный в Санкт-Петербурге в XX веке, стилизован под «нарышкинское барокко».","choices":["Воскресения Христова (Спас на Крови)","Воскресения Христова у Смоленского кладбища","Святого Исидора Юрьевского","Федоровский государев собор"],"answer":1,"steps":["Церковь Воскресения Христова находится у Смоленского кладбища в Петербурге.","В её композиции использованы ярусы и детали московского барокко."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/53.webp","alt":"Нарядная белая колокольня среди деревьев","width":132,"height":127}},{"title":"Палаты в монастыре","question":"Царские палаты этого архитектурного комплекса перестроены в XIX веке в стиле московских теремов XVII века.","choices":["Троице-Сергиева лавра","Саввино-Сторожевский монастырь","Ипатьевский монастырь","Александринский дворец"],"answer":2,"steps":["Ипатьевский монастырь в Костроме связан с призванием Михаила Романова.","Оформление его царских палат переработали в XIX веке с оглядкой на московские терема."],"figure":{"src":"assets/golden-fleece/2016/lessons/7-8-v1/54.webp","alt":"Белые стены и золотые купола монастыря","width":131,"height":143}},{"title":"Опера без пьесы","question":"Либретто этой оперы, посвященной событиям XVII века, написано композитором М. Мусоргским без литературного первоисточника.","choices":["«Борис Годунов»","«Сорочинская ярмарка»","«Хованщина»","«Ночь на лысой горе»"],"answer":2,"steps":["Мусоргский сам написал текст «Хованщины».","Для сюжета он использовал исторические материалы о стрельцах и борьбе за власть после 1682 года."]},{"title":"Герой сатиры Толстого","question":"Этого исторического деятеля А. Толстой назвал «парнем бравым».","choices":["Степан Разин","Дмитрий Пожарский","Лжедмитрий I","Борис Годунов"],"answer":2,"steps":["В стихотворной сатире «История государства Российского от Гостомысла до Тимашева» Толстой поочерёдно характеризует правителей.","«Парнем бравым» там назван Лжедмитрий I."]},{"title":"Пьеса к юбилею сцены","question":"Эту пьесу А. Островский написал к 200-летнему юбилею официального открытия театра в России.","choices":["«Комик XVII столетия»","«Таланты и поклонники»","«Снегурочка»","«Без вины виноватые»"],"answer":0,"steps":["«Комик XVII столетия» посвящён зарождению придворной сцены при Алексее Михайловиче.","Островский написал пьесу к двухсотлетию первого представления."]},{"title":"Незавершённая пьеса","question":"Пьеса о Лжедмитрии стала последним произведением, над которым работал …","choices":["Лопе де Вега","А. Сумароков","А. Толстой","Ф. Шиллер"],"answer":3,"steps":["Шиллер работал над драмой «Деметриус» о претенденте на российский престол.","Он не успел закончить пьесу."]},{"title":"Текст для симфонической поэмы","question":"Д. Шостакович написал вокально-симфоническую поэму о Степане Разине на тексты …","choices":["В. Шукшина","А. Пушкина","Е. Евтушенко","М. Цветаевой"],"answer":2,"steps":["Шостакович создал поэму «Казнь Степана Разина» для баса, хора и оркестра.","Текст взят из произведения Евгения Евтушенко."]},{"title":"Музыка по мотивам Шукшина","question":"Это произведение было написано В. Гаврилиным под впечатлением от сочинений В. Шукшина о Степане Разине.","choices":["«Перезвоны»","«Русская тетрадь»","«Скоморохи»","«Земля»"],"answer":0,"steps":["Гаврилин связал «Перезвоны» с миром героев Шукшина и народной песней.","Это многочастное хоровое произведение с сольными и инструментальными эпизодами."]}]);
